package mz.bam.seeky.android;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;
public final class PlusCoreTest {
 static int checks;static void ok(boolean value,String label){if(!value)throw new AssertionError(label);checks++;}
 interface Throwing{void run()throws Exception;}static void rejects(Throwing r,String label)throws Exception{try{r.run();}catch(Exception expected){checks++;return;}throw new AssertionError(label);}
 public static void main(String[] args)throws Exception{
  SpeechText.Prepared original=SpeechText.forVoice("A ONU leu Isaías 5:6, depois continuou.","pt");List<PronunciationRules.Rule> rules=Arrays.asList(new PronunciationRules.Rule("ONU","Organização das Nações Unidas"),new PronunciationRules.Rule("Ana","Ána"));SpeechText.Prepared prepared=PronunciationRules.apply(original,rules);ok(prepared.text.equals("A Organização das Nações Unidas leu Isaías capítulo 5, versículo 6, depois continuou."),"dictionary composes with Bible pronunciation");ok(prepared.sourceOffset(prepared.text.indexOf("Nações"))==2,"expanded name retains its source anchor");ok(prepared.sourceOffset(prepared.text.indexOf("depois"))=="A ONU leu Isaías 5:6, depois continuou.".indexOf("depois"),"words after replacement retain exact offsets");int last=-1;boolean monotonic=true;for(int i=0;i<=prepared.text.length();i++){int at=prepared.sourceOffset(i);if(at<last)monotonic=false;last=at;}ok(monotonic,"dictionary offsets never move backwards");ok(PronunciationRules.apply(SpeechText.prepare("banana Ana ANA"),rules).text.equals("banana Ána Ána"),"substitutions are case-insensitive whole words");ok(PronunciationRules.apply(SpeechText.prepare("a.* aZZ"),Arrays.asList(new PronunciationRules.Rule("a.*","literal"))).text.equals("literal aZZ"),"user text cannot inject regular expressions");ok(PronunciationRules.apply(SpeechText.prepare("IA AI"),Arrays.asList(new PronunciationRules.Rule("IA","AI"),new PronunciationRules.Rule("AI","outra"))).text.equals("AI outra"),"substitutions do not recursively rewrite their output");rejects(()->new PronunciationRules.Rule("","voz"),"empty term rejected");rejects(()->new PronunciationRules.Rule("voz",String.join("",Collections.nCopies(121,"x"))),"oversized pronunciation rejected");
  String html="<html><head><title>Isaías 5:6</title><script>if(a < b){x='João 3:16';}</script></head><body title=\"x > Isaías 5:6\"><a href='x'>João 3:16</a><p>Isaías 5:6 e João 3:16.</p></body></html>";String linked=BibleHtml.link(html);ok(linked.contains("<head><title>Isaías 5:6</title><script>if(a < b){x='João 3:16';}</script></head>"),"EPUB scripts and head remain byte-for-byte untouched");ok(linked.contains("title=\"x > Isaías 5:6\"")&&linked.contains("<a href='x'>João 3:16</a>"),"attributes and existing links remain intact");ok(linked.split("seekybible://",-1).length==3,"only visible Bible references become links");ok(linked.replaceAll("<a class=\"seeky-bible-reference\"[^>]*>([^<]+)</a>","$1").equals(html),"new links preserve all original EPUB markup and visible text");
  List<String> verses=new ArrayList<>();BibleText.Sink sink=(b,c,v,t)->verses.add(b+" "+c+":"+v+" "+t);ok(BibleText.parse(new StringReader("Isaías 5:6 O texto, com uma citação \"aberta.\nJoão 3:16 Outro texto."),sink,()->false)==2,"TXT commas and quotation marks are preserved");ok(verses.get(0).equals("Isaías 5:6 O texto, com uma citação \"aberta."),"TXT is not mistaken for CSV");verses.clear();ok(BibleText.parse(new StringReader("Livro,capítulo,versículo,texto\nIsaías,5,6,\"Linha, com vírgula\"\nJoão;3;16;Texto completo"),sink,()->false)==2,"Portuguese CSV headers and semicolon records import");ok(verses.get(0).endsWith("Linha, com vírgula"),"quoted CSV text retains embedded comma");verses.clear();BibleText.parse(new StringReader("Isaías,5,6,\"Primeira linha\nsegunda linha\""),sink,()->false);ok(verses.get(0).endsWith("Primeira linha\nsegunda linha"),"multiline CSV remains one verse");verses.clear();String usfm="\\id ISA\n\\h Isaías\n\\c 5\n\\v 6\nTexto continuado.\n\\v 7 Mais texto.\n\\id JHN\n\\c 3\n\\v 16 Outro livro.";ok(BibleText.parse(new StringReader(usfm),sink,()->false)==3,"USFM accepts continued verse text and multiple books");ok(verses.get(0).equals("Isaías 5:6 Texto continuado.")&&verses.get(2).startsWith("João 3:16"),"USFM book/chapter boundaries map correctly");rejects(()->BibleText.parse(new StringReader("Livro inexistente 5:6 texto"),sink,()->false),"unknown book rejected");rejects(()->BibleText.parse(new StringReader("Isaías,0,6,Texto"),sink,()->false),"invalid chapter rejected");rejects(()->BibleText.parse(new StringReader("Isaías 5:6 texto"),sink,()->true),"Bible import responds to cancellation");
  String text="Uma primeira ideia.\n\n"+String.join("",Collections.nCopies(900,"😀 outra ideia "));List<StudyEvidence.Part> parts=StudyEvidence.parts(text);ok(parts.size()>1&&parts.size()<=80,"source IDs are bounded and split long excerpts");boolean exact=true;for(StudyEvidence.Part part:parts)if(!part.text.equals(text.substring(part.start,part.end))||part.text.length()>0&&Character.isLowSurrogate(part.text.charAt(0))||part.text.length()>0&&Character.isHighSurrogate(part.text.charAt(part.text.length()-1)))exact=false;ok(exact,"source IDs refer to exact Unicode excerpts");ok(StudyEvidence.valid("Fonte [T1], [T999], [T2], [T1]",text).equals(Arrays.asList(1,2)),"only valid app-provided source IDs become targets");ok(StudyEvidence.numbered("Uma fonte.").equals("[T1]\nUma fonte."),"request includes explicit evidence labels");List<StudyCards.Card> cards=StudyCards.parse("Pergunta: Qual é a ideia?\nResposta: A ideia principal.\nFonte: [T1]\n\n2. Question: Why?\nAnswer: First line\ncontinued answer.\nSource: [T2]");ok(cards.size()==2,"AI cards parse Portuguese and English labels");ok(cards.get(1).back.equals("First line\ncontinued answer.")&&cards.get(0).refs.equals("[T1]"),"card answers and evidence labels are retained");ok(StudyCards.parse("Um resumo normal, sem cartões.").isEmpty(),"ordinary response requires a manual card form");rejects(()->new StudyCards.Card("","resposta",""),"empty card cannot be saved");
  File file=Files.createTempFile("seeky-cues-",".wav").toFile();try{byte[] pcm={1,2,3,4};try(CheckpointWave wave=new CheckpointWave(file,0,1,1,24000,16)){wave.out.seek(44);wave.out.write(pcm);wave.bytes=pcm.length;wave.finish(new WavInfo("Teste","Livro","Autor",1,Arrays.asList(new WavCues.Cue(0,"Introdução 😀",0)),24000));}WaveJoiner.Format format=WaveJoiner.inspect(file);byte[] bytes=Files.readAllBytes(file.toPath());ok(format.length==pcm.length&&Arrays.equals(pcm,Arrays.copyOfRange(bytes,(int)format.offset,(int)format.offset+pcm.length)),"chapter metadata leaves WAV PCM samples unchanged");List<WavCues.Cue> read;try(InputStream in=new FileInputStream(file)){read=WavCues.read(in);}ok(read.size()==1&&read.get(0).milliseconds==0&&read.get(0).label.equals("Introdução 😀"),"RIFF cue/adtl round-trip includes Unicode labels");long size=(bytes[4]&255L)|((bytes[5]&255L)<<8)|((bytes[6]&255L)<<16)|((bytes[7]&255L)<<24);ok(size==file.length()-8,"RIFF size includes the chapter index");ok(WavCues.read(new ByteArrayInputStream("not a WAV file".getBytes("UTF-8"))).isEmpty(),"non-WAV playback has no fabricated chapter index");}finally{file.delete();}
  System.out.println("PASS "+checks+" optional reading, Bible import, evidence and WAV index checks");
 }
}
